import { ReturnsRefundsService } from "@/services/returns-refunds"; import { successResponse,errorResponse } from "@/lib/api-utils"; export async function GET(_r:Request,{params}:{params:Promise<{id:string}>}){try{const {id}=await params;const x=await ReturnsRefundsService.getVendorReturnById(id);return x?successResponse(x):errorResponse("Return not found.",404)}catch{return errorResponse("Forbidden",403)}}